static std::string image_input(const std::string& source,const std::string& cached,int generation=0){if(!cached.empty()&&cached.rfind(cache_dir+"/",0)==0&&access(cached.c_str(),R_OK)==0){int w=0,h=0,n=0;if(!stbi_info(cached.c_str(),&w,&h,&n)||w>4096||h>4096||int64_t(w)*h>4000000)unlink(cached.c_str());}return fetch(muse_media::image_source(source),cached,8388608,generation);}
