 for(int i=0;i<count;i++)gains[i]=hardware?s->hw_gain[i]*10:eq_read(&s->eq_gain[i]);
 if(preset=="voice"||preset=="music"){
  const int voice_sw[]={-3,-3,-2,0,2,3,3,1,0,0},music_sw[]={3,3,2,0,-1,0,1,2,2,1};
  const int voice_hw[]={-3,-1,2,3,0},music_hw[]={3,1,0,2,2};
  for(int i=0;i<count;i++)gains[i]=10*(hardware?(preset=="voice"?voice_hw[i]:music_hw[i]):(preset=="voice"?voice_sw[i]:music_sw[i]));
 }else{bool bass=preset.find("bass")==0;int step=int(std::lround(amount*10))*(preset.find("down")!=std::string::npos?-1:1);for(int i=0;i<count;i++)if(bass?(i<(hardware?2:3)):(i>=(hardware?3:7)))gains[i]=std::clamp(gains[i]+step,-120,120);}
